 static void VerifyTopExport() {
  var root=AppDomain.CurrentDomain.BaseDirectory;var library=Library.Load(Path.Combine(root,"data","library.xml"));var items=PersonalOrder.Load(Path.Combine(root,"data","personal-order.xml")).Rank(library.Items).Take(10).ToArray();var covers=new Dictionary<string,BitmapSource>();
  foreach(var a in items){var path=Catalog.CoverPath(a.CatalogId);if(!File.Exists(path))continue;using(var stream=File.OpenRead(path)){var bitmap=BitmapFrame.Create(stream,BitmapCreateOptions.None,BitmapCacheOption.OnLoad);bitmap.Freeze();covers[a.Id]=bitmap;}}
  foreach(int count in new[]{5,10}){var bitmap=TopPoster("Мой топ аниме","Все форматы · Все жанры",items.Take(count).ToArray(),covers);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(Path.Combine(root,"top-preview-"+count+".png")))encoder.Save(stream);if(bitmap.PixelWidth!=1000||bitmap.PixelHeight<200)throw new Exception("Top export dimensions");}
 }
 TabItem BuildPersonalTop(Window owner) {
  var tab=new TabItem{Header="Личный топ"};var panel=new DockPanel{Margin=new Thickness(28,20,28,20)};tab.Content=panel;
  var header=new StackPanel();DockPanel.SetDock(header,Dock.Top);panel.Children.Add(header);header.Children.Add(Text("Мой топ",26,Ink));header.Children.Add(Text("Сначала оценка, затем ваши сравнения · фильтры независимы от библиотеки",12,Muted));
  var toolbar=new WrapPanel{Margin=new Thickness(0,14,0,10)};header.Children.Add(toolbar);
  var format=new ComboBox{ItemsSource=new[]{"Все форматы","Фильмы","Сериалы · TV / OVA / ONA"},SelectedIndex=0,Width=195,Margin=new Thickness(0,0,8,0)};toolbar.Children.Add(format);
  var genre=new ComboBox{Width=180,Margin=new Thickness(0,0,8,0)};toolbar.Children.Add(genre);
  var info=Text("",12,Muted);header.Children.Add(info);var rows=new StackPanel{Margin=new Thickness(0,12,0,0)};var scroll=new SmoothScrollViewer{Content=rows,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};panel.Children.Add(scroll);
  string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"data","personal-order.xml"),kindPath=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"data","top-kinds.xml");var order=PersonalOrder.Load(path);var kinds=new Dictionary<int,string>();
  try{if(File.Exists(kindPath))foreach(var x in XElement.Load(kindPath).Elements("anime"))kinds[(int)x.Attribute("id")]=(string)x.Attribute("kind")??"";}catch{kinds.Clear();}
  bool closed=false,busy=false;var lifetime=new CancellationTokenSource();
  Func<Anime[]> selected=()=>order.Rank(library.Items).Where(a=>PersonalOrder.Matches(a,format.SelectedIndex,genre.SelectedIndex<=0?"":(string)genre.SelectedItem,kinds)).ToArray();
  Action render=null;render=delegate {if(closed)return;rows.Children.Clear();var items=selected();info.Text=items.Length==0?"В этой категории пока нет оценённых аниме.":"Аниме: "+items.Length+" · средняя оценка: "+items.Average(a=>a.Score).ToString("0.0");
   for(int i=0;i<items.Length;i++){var a=items[i];var row=new DockPanel{Margin=new Thickness(0,0,0,14)};var edit=Btn("Карточка",delegate{OpenAnimeCard(a,owner);render();});edit.VerticalAlignment=VerticalAlignment.Center;DockPanel.SetDock(edit,Dock.Right);row.Children.Add(edit);var cover=new Image{Width=48,Height=70,Stretch=Stretch.Uniform,Margin=new Thickness(0,0,12,0)};DockPanel.SetDock(cover,Dock.Left);row.Children.Add(cover);LoadCover(cover,a.CatalogId,a.CoverUrl,lifetime.Token);var texts=new StackPanel();texts.Children.Add(Text((i+1)+". "+a.Title,16,Ink));texts.Children.Add(Text("★ "+a.Score+" / 10 · "+MalImport.StatusLabel(a.Status),12,Muted));row.Children.Add(texts);rows.Children.Add(row);}
  };
  // Refresh after modal edits as well as after changing a category.

  toolbar.Children.Add(Btn("Сравнить",delegate{CompareTop(owner,order,selected,path);render();}));toolbar.Children.Add(Btn("Сохранить картинку",delegate{ExportTop(owner,selected(),format.SelectedItem+" · "+(genre.SelectedItem??"Все жанры"));}));
  format.SelectionChanged+=delegate{scroll.ResetToTop();render();};genre.SelectionChanged+=delegate{scroll.ResetToTop();render();};
  tab.AddHandler(System.Windows.Controls.Primitives.Selector.SelectedEvent,new RoutedEventHandler(async delegate(object sender,RoutedEventArgs e){if(e.OriginalSource!=tab||closed)return;var previous=genre.SelectedItem as string;var genres=new[]{"Все жанры"}.Concat(library.Items.Where(a=>a.Score>0).SelectMany(a=>LibraryView.Genres(a)).Distinct().OrderBy(x=>x)).ToArray();genre.ItemsSource=genres;genre.SelectedIndex=Math.Max(0,Array.IndexOf(genres,previous));render();if(busy)return;busy=true;
   try{var ids=library.Items.Where(a=>a.Score>0&&a.CatalogId>0&&!kinds.ContainsKey(a.CatalogId)).Select(a=>a.CatalogId).Distinct().ToArray();for(int offset=0;offset<ids.Length;offset+=50){var entries=await Catalog.ByIds(ids.Skip(offset).Take(50),lifetime.Token);if(closed)return;foreach(var entry in entries)kinds[entry.Id]=entry.Kind;}
    if(ids.Length>0){new XElement("kinds",kinds.Select(k=>new XElement("anime",new XAttribute("id",k.Key),new XAttribute("kind",k.Value)))).Save(kindPath+".tmp");if(File.Exists(kindPath))File.Replace(kindPath+".tmp",kindPath,kindPath+".bak");else File.Move(kindPath+".tmp",kindPath);}render();
   }catch{if(!closed)info.Text+=" · Не все форматы удалось уточнить в каталоге";}finally{busy=false;}
  }));owner.Closed+=delegate{closed=true;lifetime.Cancel();lifetime.Dispose();};return tab;
 }
 void CompareTop(Window owner,PersonalOrder order,Func<Anime[]> selected,string path) {
  var dialog=new Window{Title="Что нравится больше?",Owner=owner,Width=700,Height=530,WindowStartupLocation=WindowStartupLocation.CenterOwner};StyleWindow(dialog);var root=new StackPanel{Margin=new Thickness(24)};dialog.Content=new SmoothScrollViewer{Content=root,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};root.Children.Add(Text("Что нравится больше?",25,Ink));root.Children.Add(Text("Сравниваются только одинаковые оценки в выбранной категории. Оценки и прогресс не меняются.",12,Muted));var info=Text("",12,Muted);root.Children.Add(info);var cards=new Grid{Margin=new Thickness(0,16,0,16)};cards.ColumnDefinitions.Add(new ColumnDefinition());cards.ColumnDefinitions.Add(new ColumnDefinition());root.Children.Add(cards);var actions=new WrapPanel();root.Children.Add(actions);var skipped=new HashSet<string>();Anime[] pair=null;List<TopVote> undoVotes=null;var lifetime=new CancellationTokenSource();
  Action show=null;show=delegate{cards.Children.Clear();pair=order.Pair(library.Items.ToArray(),selected(),skipped);if(pair==null){info.Text="Доступные пары закончились. Можно вернуться к топу или вернуть пропущенные.";return;}info.Text="Оба аниме: "+pair[0].Score+" / 10 · выберите любимое";for(int i=0;i<2;i++){var winner=pair[i];var loser=pair[1-i];var button=Btn("",delegate{try{var previous=order.Votes.ToList();order.Choose(library.Items.ToArray(),winner,loser,path);undoVotes=previous;show();}catch(Exception ex){info.Text=ex.Message;}});button.IsEnabled=!storageBlocked;button.Padding=new Thickness(16);var body=new StackPanel();var cover=new Image{Height=210,Stretch=Stretch.Uniform};body.Children.Add(cover);LoadCover(cover,winner.CatalogId,winner.CoverUrl,lifetime.Token);var title=Text(winner.Title,17,Ink);title.MaxWidth=250;title.Margin=new Thickness(0,10,0,0);body.Children.Add(title);button.Content=body;Grid.SetColumn(button,i);cards.Children.Add(button);}Reveal(cards);};
  actions.Children.Add(Btn("Пропустить",delegate{if(pair!=null)skipped.Add(PersonalOrder.Key(pair[0],pair[1]));show();}));actions.Children.Add(Btn("Вернуть пропущенные",delegate{skipped.Clear();show();}));actions.Children.Add(Btn("Отменить выбор",delegate{if(undoVotes==null)return;try{var previous=new PersonalOrder{Votes=undoVotes};previous.Save(path);order.Votes=undoVotes;undoVotes=null;show();}catch(Exception ex){info.Text=ex.Message;}}));var close=Btn("Готово",delegate{dialog.Close();});close.IsCancel=true;actions.Children.Add(close);dialog.Closed+=delegate{lifetime.Cancel();lifetime.Dispose();};show();dialog.ShowDialog();
 }
 internal static BitmapSource TopPoster(string title,string category,Anime[] items,Dictionary<string,BitmapSource> covers) {
  var paper=new StackPanel{Width=1000,Background=new SolidColorBrush(Color.FromRgb(248,238,204))};var heading=new TextBlock{Text=title,FontFamily=new FontFamily("Georgia"),FontSize=38,Foreground=new SolidColorBrush(Color.FromRgb(71,54,29)),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(40,32,40,8)};paper.Children.Add(heading);paper.Children.Add(new TextBlock{Text=category,FontSize=17,Foreground=Brushes.SaddleBrown,Margin=new Thickness(40,0,40,22),TextWrapping=TextWrapping.Wrap});
  var grid=new Grid{Margin=new Thickness(30,0,30,20)};grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition());paper.Children.Add(grid);
  for(int i=0;i<items.Length;i++){if(i%2==0)grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(185)});var a=items[i];var border=new Border{Background=new SolidColorBrush(Color.FromRgb(255,249,225)),CornerRadius=new CornerRadius(8),Padding=new Thickness(12),Margin=new Thickness(6)};Grid.SetRow(border,i/2);Grid.SetColumn(border,i%2);grid.Children.Add(border);var dock=new DockPanel();border.Child=dock;BitmapSource bitmap;covers.TryGetValue(a.Id,out bitmap);var cover=new Image{Width=100,Height=145,Source=bitmap,Stretch=Stretch.Uniform,Margin=new Thickness(0,0,15,0)};DockPanel.SetDock(cover,Dock.Left);dock.Children.Add(cover);var text=new StackPanel();text.Children.Add(new TextBlock{Text="#"+(i+1)+"   ★ "+a.Score+" / 10",FontSize=20,Foreground=Brushes.SaddleBrown});text.Children.Add(new TextBlock{Text=a.Title,FontSize=22,FontFamily=new FontFamily("Segoe UI"),Foreground=new SolidColorBrush(Color.FromRgb(71,54,29)),TextWrapping=TextWrapping.Wrap,TextTrimming=TextTrimming.CharacterEllipsis,MaxHeight=112,Margin=new Thickness(0,10,0,0)});dock.Children.Add(text);}
  paper.Children.Add(new TextBlock{Text="Anime Tracker · личный топ",FontSize=14,Foreground=Brushes.SaddleBrown,Margin=new Thickness(40,0,40,24)});paper.Measure(new Size(1000,Double.PositiveInfinity));paper.Arrange(new Rect(0,0,1000,paper.DesiredSize.Height));paper.UpdateLayout();var result=new RenderTargetBitmap(1000,(int)Math.Ceiling(paper.ActualHeight),96,96,PixelFormats.Pbgra32);result.Render(paper);result.Freeze();return result;
 }
 void ExportTop(Window owner,Anime[] selected,string category) {
  if(selected.Length==0){MessageBox.Show(owner,"В выбранной категории пока нет оценённых аниме.","Экспорт топа");return;}
  var snapshot=selected.Select(a=>a.Copy()).ToArray();var dialog=new Window{Title="Картинка личного топа",Owner=owner,Width=660,Height=740,MinWidth=500,MinHeight=450,WindowStartupLocation=WindowStartupLocation.CenterOwner};StyleWindow(dialog);var root=new DockPanel{Margin=new Thickness(20)};dialog.Content=root;var controls=new StackPanel();DockPanel.SetDock(controls,Dock.Top);root.Children.Add(controls);controls.Children.Add(Text("Заголовок подборки",12,Muted));var title=new TextBox{Text="Мой топ аниме",MaxLength=100,Margin=new Thickness(0,5,0,10)};controls.Children.Add(title);var count=new ComboBox{ItemsSource=new[]{"Топ-5","Топ-10"},SelectedIndex=0,Width=120,HorizontalAlignment=HorizontalAlignment.Left};controls.Children.Add(count);var info=Text("Загружаю обложки…",12,Muted);controls.Children.Add(info);var save=new Button{Content="Сохранить PNG",IsEnabled=false,Margin=new Thickness(0,12,0,0)};DockPanel.SetDock(save,Dock.Bottom);root.Children.Add(save);var preview=new Image{Stretch=Stretch.Uniform};root.Children.Add(new SmoothScrollViewer{Content=preview,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});var covers=new Dictionary<string,BitmapSource>();BitmapSource poster=null;bool closed=false,ready=false;var lifetime=new CancellationTokenSource();
  Action render=delegate{if(!ready||closed)return;var items=snapshot.Take(count.SelectedIndex==0?5:10).ToArray();poster=TopPoster(String.IsNullOrWhiteSpace(title.Text)?"Мой топ аниме":title.Text.Trim(),category,items,covers);preview.Source=poster;info.Text="В подборке: "+items.Length+" · "+poster.PixelWidth+" × "+poster.PixelHeight+" px"+(covers.Count<items.Length?" · некоторые обложки недоступны":"");save.IsEnabled=true;};title.TextChanged+=delegate{render();};count.SelectionChanged+=delegate{render();};
  dialog.Loaded+=async delegate{foreach(var a in snapshot.Take(10)){try{var bitmap=await Catalog.Cover(a.CatalogId,a.CoverUrl,lifetime.Token);if(closed)return;if(bitmap!=null)covers[a.Id]=bitmap;}catch(OperationCanceledException){if(closed)return;}catch{}}ready=true;render();};
  save.Click+=delegate{var picker=new Microsoft.Win32.SaveFileDialog{Filter="PNG изображение|*.png",FileName="Мой топ аниме.png",DefaultExt=".png",AddExtension=true};if(picker.ShowDialog(dialog)!=true)return;try{var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(poster));using(var stream=File.Create(picker.FileName))png.Save(stream);info.Text="Сохранено: "+picker.FileName;}catch(Exception ex){info.Text="Не удалось сохранить: "+ex.Message;}};dialog.Closed+=delegate{closed=true;lifetime.Cancel();lifetime.Dispose();};dialog.ShowDialog();
 }
